// --- SAFETY CHECK ---
if (!monster.stats) return "";

// --- 1. CONFIGURATION & HELPERS ---

const statNames = ["Str", "Dex", "Con", "Int", "Wis", "Cha"];
const pairs = [[0, 3], [1, 4], [2, 5]];

// Helper: Calculate Modifier
const getMod = (score) => Math.floor((score - 10) / 2);

// Helper: Add plus sign to positive numbers
const formatNum = (num) => (num >= 0 ? "+" + num : num);

// Helper: Parse CR to get Proficiency Bonus
const getPB = (crVal) => {
    let cr = 0;
    if (typeof crVal === 'string' && crVal.includes('/')) {
        const parts = crVal.split('/');
        cr = parseInt(parts[0]) / parseInt(parts[1]);
    } else {
        cr = parseFloat(crVal) || 0;
    }
    return Math.max(2, Math.floor(2 + ((cr - 1) / 4)));
};

// Helper: Robust Save Checker
const getSaveMod = (statIndex, mod, monster, pb) => {
    const fullNames = ["strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma"];
    const shortNames = ["str", "dex", "con", "int", "wis", "cha"];
    const targetFull = fullNames[statIndex];
    const targetShort = shortNames[statIndex];

    if (!monster.saves) return mod;

    if (Array.isArray(monster.saves)) {
        for (const entry of monster.saves) {
            if (typeof entry === 'string') {
                if (entry.toLowerCase() === targetFull || entry.toLowerCase() === targetShort) return mod + pb;
            } else if (typeof entry === 'object' && entry !== null) {
                for (const key of Object.keys(entry)) {
                    if (key.toLowerCase() === targetFull || key.toLowerCase() === targetShort) return parseInt(entry[key]);
                }
            }
        }
    } else if (typeof monster.saves === 'object') {
         for (const key of Object.keys(monster.saves)) {
             if (key.toLowerCase() === targetFull || key.toLowerCase() === targetShort) return parseInt(monster.saves[key]);
         }
    }
    return mod;
};

// --- 2. THEME DETECTION & PALETTE ---

// Detect Obsidian Dark Mode
const isDark = document.body.classList.contains("theme-dark");

// Define Color Palettes
// Light: Your original pastel colors
// Dark: Deep, low-light versions of the same tints (Warm/Pinkish & Greenish/Bluish)
const palette = {
    row0: {
        name: isDark ? "#2c2925" : "#e9e5d6", // Dark Warm Brown vs Light Beige
        mod:  isDark ? "#2e2525" : "#e2d5d5"  // Dark Muted Red vs Light Pinkish
    },
    row1: {
        name: isDark ? "#252b25" : "#dbe0db", // Dark Muted Green vs Light Greenish
        mod:  isDark ? "#25252e" : "#dbd9df"  // Dark Muted Blue vs Light Purple/Grey
    }
};

// --- 3. MAIN LOGIC ---

const pb = getPB(monster.cr);

// Main Container
const container = document.createElement("div");
container.style.display = "flex";
container.style.justifyContent = "space-between";
container.style.width = "100%";
container.style.gap = "4px";
container.style.marginTop = "0px";
container.style.marginBottom = "12px"; 

// Loop to create the 3 Tables
pairs.forEach(pair => {
    const table = document.createElement("table");

    // Layout Logic
    table.style.flex = "1 1 0px"; 
    table.style.maxWidth = "140px"; 

    table.style.tableLayout = "fixed"; 
    table.style.width = "100%"; 
    table.style.minWidth = "0"; 

    table.style.borderCollapse = "collapse";
    table.style.margin = "0";

    table.style.setProperty("font-size", "13.5px", "important");
    table.style.setProperty("padding", "0", "important");
    table.style.backgroundColor = "transparent";

    // --- ROW 1: HEADERS ---
    const thead = document.createElement("tr");

    const createHeader = (text) => {
        const th = document.createElement("th");
        th.innerText = text;
        th.style.fontSize = "10px";
        // Lighten the header text slightly for dark mode readbility if needed, 
        // but #7c7c7c usually works on both.
        th.style.color = "#7c7c7c"; 
        th.style.fontWeight = "normal"; 
        th.style.verticalAlign = "bottom"; 
        th.style.lineHeight = "1"; 
        th.style.textAlign = "center";
        th.style.padding = "0 2px 2px 2px"; 
        th.style.border = "none";
        th.style.overflow = "hidden";
        th.style.whiteSpace = "nowrap";
        return th;
    };

    thead.appendChild(createHeader(""));       
    thead.appendChild(createHeader(""));       
    thead.appendChild(createHeader("MOD"));    
    thead.appendChild(createHeader("SAVE"));   
    table.appendChild(thead);

    // --- ROWS 2 & 3: STAT DATA ---
    pair.forEach((statIndex, rowIndex) => {
        const score = monster.stats[statIndex];
        const mod = getMod(score);
        const save = getSaveMod(statIndex, mod, monster, pb);

        // Select Colors based on Row Index using our adaptive palette
        const colors = rowIndex === 0 ? palette.row0 : palette.row1;

        const row = document.createElement("tr");

        // Helper to create data cells
        const createCell = (content, isBold = false, color = null, bgColor = null) => {
            const td = document.createElement("td");

            if (content instanceof Node) {
                td.appendChild(content);
            } else {
                td.innerText = content; 
            }

            td.style.textAlign = "center";

            td.style.setProperty("padding", "2px", "important");

            td.style.border = "none";
            // If this is the Top Row (Index 0), add a bottom border.
            // Using a CSS variable ensures the border color matches the theme's background color
            if (rowIndex === 0) {
                td.style.borderBottom = "2px solid var(--active-background-color)"; 
            }

            td.style.verticalAlign = "middle";
            td.style.lineHeight = "1"; 
            td.style.overflow = "hidden";
            td.style.whiteSpace = "nowrap"; 
            td.style.fontSize="var(--active-property-name-font-size)";

            if (isBold) td.style.fontWeight = "bold";
            if (color) td.style.color = color;
            if (bgColor) td.style.backgroundColor = bgColor;

            return td;
        };

        // --- TEXT COLOR CONFIGURATION ---
        // Applies the theme's property color to the text. 
        const textColor = "var(--active-property-name-font-color)";

        // Col 1: Name
        const statNameElement = document.createElement("span");
        statNameElement.innerText = statNames[statIndex];

        statNameElement.style.margin = "0";
        statNameElement.style.padding = "0 4px";
        statNameElement.style.fontVariant="var(--active-heading-font-variant)";
        statNameElement.style.fontWeight="var(--active-property-name-font-weight)";
        statNameElement.style.fontSize="var(--active-property-name-font-size)";

        const nameCell = createCell(statNameElement, false, textColor, colors.name);
        nameCell.style.textAlign = "left";

        row.appendChild(nameCell);

        // Col 2: Score
        row.appendChild(createCell(score, false, textColor, colors.name));

        // Col 3: Mod (Applied textColor here)
        row.appendChild(createCell(formatNum(mod), false, textColor, colors.mod));

        // Col 4: Save (Applied textColor here)
        row.appendChild(createCell(formatNum(save), false, textColor, colors.mod));

        table.appendChild(row);
    });

    container.appendChild(table);
});

return container;

