    // Check for the tag pattern
    const tagRegex = /<STATBLOCK-MARKDOWN-LINK>(.*?)<STATBLOCK-MARKDOWN-LINK>/;
    const match = str.match(tagRegex);

    if (match) {
        const innerContent = match[1];
        let path = innerContent;
        let display = innerContent;

        // Handle pipe separator: path/to/file|Display Name
        if (innerContent.includes('|')) {
            const parts = innerContent.split('|');
            path = parts[0];
            display = parts[1];
        }

        const cleanDisplay = toTitleCase(display);

        // Return actual HTML link
        return `<a class="internal-link" data-href="${path}" href="${path}" target="_blank" rel="noopener nofollow">${cleanDisplay}</a>`;
    }

    // Fallback for plain text (e.g. "perception")
    return toTitleCase(str);
};

