setTimeout(() => {
  // ── 1. CHALLENGE / PROFICIENCY ──────────────────────────────────────
  const containers = document.querySelectorAll('.statblock-item-container.property-container');
  let challengeContainer = null;
  let proficiencyContainer = null;

  containers.forEach(cont => {
    const nameSpan = cont.querySelector('.property-name');
    if (nameSpan) {
      const text = nameSpan.textContent.trim();
      if (text.includes('Challenge')) challengeContainer = cont;
      if (text.includes('Proficiency')) proficiencyContainer = cont;
    }
  });

  if (challengeContainer && proficiencyContainer && proficiencyContainer.parentNode) {
    challengeContainer.insertAdjacentElement('afterend', proficiencyContainer);
    const wrapper = document.createElement('div');
    wrapper.style.display = 'flex';
    wrapper.style.justifyContent = 'space-between';
    wrapper.style.alignItems = 'baseline';
    wrapper.style.gap = '16px';
    wrapper.style.width = '100%';
    challengeContainer.parentNode.insertBefore(wrapper, challengeContainer);
    wrapper.appendChild(challengeContainer);
    wrapper.appendChild(proficiencyContainer);
  }

  // ── 2. AC / INITIATIVE ROW ───────────────────────────────────────────
  //
  // TUNING: How many pixels to reserve on the right for the creature image.
  // Initiative's RIGHT EDGE will be pinned exactly here via position:absolute.
  // Increase → Initiative moves left. Decrease → Initiative moves right.
  const IMAGE_PADDING = '95px';

  const sbFlex = document.querySelector('.sb-flex-50');
  if (!sbFlex) return;

  const flexItems = sbFlex.querySelectorAll('.statblock-item-container');
  let acItem = null;
  let initItem = null;
  flexItems.forEach(item => {
    const nm = item.querySelector('.property-name');
    if (!nm) return;
    if (nm.textContent.includes('Armor')) acItem = item;
    if (nm.textContent.includes('Initiative')) initItem = item;
  });

  if (!acItem || !initItem) return;

  // Flatten both items: remove inner <p> wrappers, force nowrap inline display
  const flattenItem = (item) => {
    const mdDiv = item.querySelector('.statblock-markdown');
    if (mdDiv) {
      const ps = mdDiv.querySelectorAll('p');
      ps.forEach(p => {
        while (p.firstChild) mdDiv.insertBefore(p.firstChild, p);
        p.remove();
      });
      mdDiv.style.display = 'inline';
      mdDiv.style.whiteSpace = 'nowrap';
    }
    item.style.display = 'inline-flex';
    item.style.alignItems = 'baseline';
    item.style.flexWrap = 'nowrap';
    item.style.whiteSpace = 'nowrap';
    item.style.flexShrink = '0';
    const nm = item.querySelector('.property-name');
    if (nm) { nm.style.whiteSpace = 'nowrap'; nm.style.flexShrink = '0'; }
  };

  flattenItem(acItem);
  flattenItem(initItem);

  // Decide layout based on AC text length.
  // TUNING: increase threshold if Initiative drops too early,
  //         decrease if AC text overlaps Initiative.
  const AC_WRAP_THRESHOLD = 18; // characters in AC value text

  const acValueEl = acItem.querySelector('.statblock-markdown') || acItem;
  const acText = acValueEl.textContent || '';
  const acTooLong = acText.trim().length > AC_WRAP_THRESHOLD;

  // Build the row
  const row = document.createElement('div');
  row.style.width = '100%';
  row.style.paddingRight = IMAGE_PADDING;
  row.style.boxSizing = 'border-box';
  row.style.position = 'relative';
  row.style.display = 'block';
  row.style.lineHeight = '1.4';

